    'admin_fair-defaults.ai_analysis_help' => 'Коли увімкнено, аналітики можуть використовувати AI для оцінки реалістичного ALE, величин первинних/вторинних втрат і рекомендованого покриття кіберстрахування на основі всіх доступних даних безпеки постачальника (сигнали Shodan, ризики UpGuard, дані про вразливості та фінансовий контекст).',
    'admin_fair-defaults.ai_disabled_help' => 'AI-розрахунки FAIR потребують увімкненої платформи AI (OpenWebUI або LibreChat). Спочатку <a href="admin.php?section=ai-integration">налаштуйте параметри AI Integration</a>.',
    'admin_fair-defaults.ai_enable_checkbox_label' => 'Увімкнути AI-розрахунки FAIR',
