    'admin_scheduler.timezone_label' => 'Часовий пояс',
    'admin_shadow-saas-grip.abort_failed_prefix' => 'Не вдалося перервати синхронізацію: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'Перервати активну синхронізацію Grip?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'Перервати активну синхронізацію HERO?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security виявляє та безперервно моніторить SaaS-of-Record застосунки у вашому середовищі.
Ця інтеграція:<br><br>
<strong>&bull; Дзеркалить дані Grip:</strong> Підтягує повний перелік SaaS / користувачів / сповіщень до таблиць <code>shadow_saas_grip_*</code>.<br>
<strong>&bull; Гідратує Shadow SaaS:</strong> Проєктує кожен SaaS-застосунок до наявного списку Shadow SaaS, нормалізуючи URL-адресу до її реєстровного домену, тож зіставлення постачальників працює так само, як імпорт CSV.<br>
<strong>&bull; Відстежує ризик:</strong> Зберігає оцінку ризику Grip, тег санкції, кількість OAuth-областей, класифікацію глибини AI, підтримку MFA / SAML і метадані основного контакту.<br>
<strong>&bull; Залишається актуальною:</strong> Повторно запускається за налаштованим розкладом cron; адміністратори також можуть ініціювати негайний фоновий запуск кнопкою "Run Now" вище.',
    'admin_shadow-saas-grip.about_grip_heading' => 'Про інтеграцію Grip',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security виявляє сторонніх SaaS-постачальників і проблеми, що їх стосуються, у вашому середовищі.
Ця інтеграція:<br><br>
<strong>&bull; Дзеркалить дані HERO:</strong> Підтягує постачальників / проблеми / користувачів окремих постачальників до таблиць <code>shadow_saas_hero_*</code>.<br>
<strong>&bull; Гідратує Shadow SaaS:</strong> Проєктує кожного постачальника до наявного списку Shadow SaaS за реєстровним доменом, тож зіставлення працює так само, як імпорт CSV.<br>
<strong>&bull; Відстежує ризик:</strong> Виводить оцінку ризику 1-5 із найгіршої відкритої проблеми на кожного постачальника (та сама шкала 1-5, що використовує Grip) і фіксує статус постачальника та аспекти залучення.<br>
<strong>&bull; Залишається актуальною:</strong> Повторно запускається спільним завданням запланованої повторної гідратації; адміністратори також можуть ініціювати негайний запуск кнопкою "Run Now" нижче.',
    'admin_shadow-saas-grip.about_hero_heading' => 'Про інтеграцію HERO',
    'admin_shadow-saas-grip.api_key_label' => 'Ключ API',
    'admin_shadow-saas-grip.api_reference_heading' => 'Довідник API',
    'admin_shadow-saas-grip.api_token_help' => 'Надсилається як HTTP-заголовок <code>access-token</code> у кожному запиті. Залиште порожнім, щоб зберегти наявний токен.',
    'admin_shadow-saas-grip.api_token_label' => 'Токен API',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'Хост URL-адреси API не дозволено.',
    'admin_shadow-saas-grip.api_url_invalid' => 'URL-адреса API має бути коректною http(s) URL-адресою.',
    'admin_shadow-saas-grip.api_url_label' => 'URL-адреса API',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' застосунків з користувачами',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Наразі зберігається ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>Live</strong> викликає API Grip для кожної сторінки (завжди актуально, більше навантаження на API). <strong>Local (гідратовано/кешовано)</strong> обслуговує гідратовані таблиці <code>shadow_saas_grip_*</code> у базі даних - менше навантаження на API - а відсутній знімок окремого застосунку одноразово завантажується з API, після чого кешується. У режимі Local кожна синхронізація <strong>повністю оновлює</strong> дані: дзеркальні таблиці Grip очищаються та повторно гідратуються з API.',
    'admin_shadow-saas-grip.data_source_label' => 'Джерело даних',
    'admin_shadow-saas-grip.data_source_live' => 'Live - запит до API Grip під час кожного перегляду',
    'admin_shadow-saas-grip.data_source_local' => 'Local (гідратовано/кешовано) - обслуговування з бази даних',
    'admin_shadow-saas-grip.download_postman_json' => 'Завантажити Postman (JSON)',
