    'admin_shadow-saas-grip.enable_hero' => 'Увімкнути інтеграцію з HERO Security',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Увімкнути заплановану повторну гідратацію',
    'admin_shadow-saas-grip.enable_zscaler' => 'Увімкнути блокування URL-категорії Zscaler при відмові',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Введіть ключ API адміністратора',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'Не вдалося очистити ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Передавати інформацію про витоки Grip до Breach&nbsp;/&nbsp;Cyber Alerts',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'Усі дані Grip очищено: ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' дзеркальних таблиць очищено, ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' рядків Shadow SaaS видалено, а також ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' записів постачальників очищено від нанесеної телеметрії Grip.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Перелік кінцевих точок публічного API Grip Security (база сервера <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, автоматично згенерований OpenAPI 3.1). Синхронізація FairTPRM використовує кінцеві точки читання (GET), позначені як <em>used by sync</em>; повний перелік &mdash; включно з групами Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions та AI&nbsp;Agents &mdash; наведено у завантаженнях OpenAPI та Postman нижче. Вилучення домену нормалізує URL-адреси до їхнього реєстровного домену (наприклад, <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'Заголовок автентифікації: <code>access-token: &lt;your-token&gt;</code>. Змінна <code>accessToken</code> колекції Postman має значення <code>REPLACE_ME</code>; підставте токен вашого тенанта перед надсиланням запитів.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'Префіксована тенантом URL-адреса Grip з коренем <code>/public/saas</code> (наприклад, <code>https://tenant.dep.grip.security/public/saas</code>). Суміжні кінцеві точки (<code>/public/users</code>, <code>/public/alerts</code>) виводяться з цього хоста.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Сервер (базова URL-адреса тенанта)',
    'admin_shadow-saas-grip.grip_breach_help' => 'Під час кожної запланованої повторної гідратації (та ручного запуску <strong>Run&nbsp;Now</strong> нижче) сповіщення Grip "Security Incident Detected" записуються до системи <a href="breach-alerts.php">Breach&nbsp;/&nbsp;Cyber Alerts</a> (з дедуплікацією). Витоки для онбордингованого постачальника прив\'язуються до цього постачальника; витоки для застосунку без онбордингованого постачальника все одно фіксуються та позначаються тегом <strong>Shadow&nbsp;SaaS</strong> із зазначенням кількості потенційно постраждалих користувачів. Потребує увімкненого Grip (вище) <em>та</em> налаштування Breach&nbsp;/&nbsp;Cyber Alert у розділі <a href="admin.php?section=email">Email &amp; Alerts</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'Не вдалося оновити конфігурацію Grip: ',
    'admin_shadow-saas-grip.grip_config_updated' => 'Конфігурацію Grip успішно оновлено.',
    'admin_shadow-saas-grip.grip_connection_heading' => 'З\'єднання з Grip Security',
    'admin_shadow-saas-grip.grip_enable_help' => 'Коли увімкнено, заплановані та позапланові синхронізації підтягуватимуть SaaS-застосунки, користувачів і сповіщення з вашого тенанта Grip до списку Shadow SaaS.',
    'admin_shadow-saas-grip.grip_ep_alerts_list' => 'Список сповіщень безпеки (серйозність, пом\'якшення, пов\'язана сутність). <em>Used by sync.</em>',
    'admin_shadow-saas-grip.grip_ep_label_add' => 'Додати мітку до SaaS-застосунку.',
    'admin_shadow-saas-grip.grip_ep_label_remove' => 'Видалити мітку з SaaS-застосунку.',
