    'admin_shadow-saas-grip.hero_api_reference_intro' => 'Перелік кінцевих точок публічного API HERO, що використовується цією інтеграцією. Автентифікація - OAuth 2.0 client-credentials &rarr; токен Bearer; кінцеві точки списків використовують курсорну пагінацію (<code>next_cursor</code> &rarr; <code>cursor</code>).',
    'admin_shadow-saas-grip.hero_auth_help' => 'Автентифікація: <code>Authorization: Bearer &lt;token&gt;</code> на всіх кінцевих точках даних. Термін дії токенів спливає приблизно через 1 годину.',
    'admin_shadow-saas-grip.hero_base_url_help' => 'База публічного API HERO, наприклад <code>https://api.herosecurity.ai/stable</code>. Кінцеві точки (<code>/v1/vendors</code>, <code>/v1/issues</code>) виводяться з цього хоста.',
    'admin_shadow-saas-grip.hero_base_url_label' => 'Сервер (базова URL-адреса)',
    'admin_shadow-saas-grip.hero_client_id_help' => 'OAuth 2.0 <code>client_id</code> з панелі адміністратора HERO.',
    'admin_shadow-saas-grip.hero_client_secret_help' => 'OAuth 2.0 <code>client_secret</code>, що обмінюється на короткочасний токен Bearer (client-credentials grant). Зберігається у зашифрованому вигляді. Залиште порожнім, щоб зберегти наявне значення.',
    'admin_shadow-saas-grip.hero_client_secret_placeholder' => 'client_secret (відображається одноразово під час створення)',
    'admin_shadow-saas-grip.hero_config_update_failed_prefix' => 'Не вдалося оновити конфігурацію HERO: ',
    'admin_shadow-saas-grip.hero_config_updated' => 'Конфігурацію HERO успішно оновлено.',
    'admin_shadow-saas-grip.hero_connection_heading' => 'З\'єднання з HERO Security',
    'admin_shadow-saas-grip.hero_disabled_grip' => ' Grip було вимкнено - одночасно може бути активним лише один провайдер.',
    'admin_shadow-saas-grip.hero_enable_help' => 'Коли увімкнено, заплановані та позапланові синхронізації підтягують постачальників, проблеми та користувачів окремих постачальників з HERO до списку Shadow SaaS. Увімкнення HERO вимикає Grip - одночасно може бути активним лише один провайдер.',
    'admin_shadow-saas-grip.hero_ep_auth' => 'Обміняти client_id + client_secret на токен Bearer.',
