    'admin_shadow-saas-grip.hero_ep_vendor_users' => 'Список користувачів, помічених у взаємодії з постачальником.',
    'admin_shadow-saas-grip.hero_ep_vendors_list' => 'Список постачальників (курсорна пагінація; <code>page_size</code> &le; 250).',
    'admin_shadow-saas-grip.hero_mirror_issues_desc' => 'Один рядок на кожну проблему безпеки HERO (тип, серйозність, статус, постачальник).',
    'admin_shadow-saas-grip.hero_mirror_users_desc' => 'Основний контакт на кожного постачальника - користувач із найвищою активністю електронної пошти, що використовується як менеджер зі співпраці.',
    'admin_shadow-saas-grip.hero_mirror_vendors_desc' => 'Один рядок на кожного постачальника HERO (статус, аспекти, виведена оцінка ризику 1-5, повне навантаження).',
    'admin_shadow-saas-grip.hero_pacing_help' => 'HERO обмежує швидкість викликів API (~60 запитів на хвилину для всього облікового запису). Ці параметри визначають, як регулюється темп синхронізації користувачів окремих постачальників.',
    'admin_shadow-saas-grip.hero_security_link' => 'HERO Security &rarr;',
    'admin_shadow-saas-grip.hero_test_failed_prefix' => 'Перевірка HERO не вдалася: ',
    'admin_shadow-saas-grip.hero_throttle_help' => 'Пауза між запитом користувачів кожного постачальника. ~1100&nbsp;мс утримує повну синхронізацію трохи нижче ліміту HERO ~60/хв. Менше значення пришвидшує, але спричиняє відступи через ліміт швидкості (429).',
    'admin_shadow-saas-grip.hero_throttle_label' => 'Затримка між викликами постачальників (мс)',
    'admin_shadow-saas-grip.hero_timeout_help' => 'Скільки часу чекати на користувачів одного постачальника перед його пропуском. Менше значення означає, що дуже великі тенанти, які зависають, швидко зазнають невдачі, а не гальмують запуск на весь тайм-аут.',
    'admin_shadow-saas-grip.hero_timeout_label' => 'Тайм-аут отримання користувачів (секунди)',
