    'admin_shadow-saas-grip.providers_mutually_exclusive_help' => 'Grip і Hero є взаємовиключними - увімкнення одного вимикає інший. Активний провайдер (&#9679;) живить спільне блокування Zscaler і заплановану повторну гідратацію нижче.',
    'admin_shadow-saas-grip.rehydration_started' => 'Повторну гідратацію Shadow SaaS запущено у фоновому режимі. Оновіть сторінку за кілька секунд, щоб побачити останній запуск.',
