    'admin_shadow-saas-grip.save_schedule_button' => 'Зберегти розклад',
    'admin_shadow-saas-grip.sched_enable_help' => 'Коли увімкнено, завдання встановлюється до системного crontab і запускається за наведеним нижче розкладом. Файл блокування запобігає накладанню запусків. Запуск використовує того провайдера, який увімкнено.',
    'admin_shadow-saas-grip.sched_rehydration_heading' => 'Запланована повторна гідратація',
    'admin_shadow-saas-grip.sched_rehydration_intro' => 'Запускає увімкненого провайдера Shadow SaaS (Grip або Hero) за розкладом, оновлюючи дзеркальні таблиці та список Shadow SaaS. Наведений нижче розклад автоматично встановлюється до системного crontab &mdash; без ручного редагування crontab, і він зберігається після перезапусків контейнера.',
