    'admin_shadow-saas-grip.truncate_all_confirm' => 'Очистити ВСІ локальні дані Grip? Це остаточно видалить кожен дзеркальний рядок Grip (застосунки, користувачів, сповіщення, користувачів окремих застосунків), видалить усі спроєктовані Grip рядки Shadow SaaS і очистить куровану телеметрію Grip, нанесену на записи постачальників (вкладка \'SaaS Data\' постачальника). Наступна синхронізація повторно гідратує їх з API Grip. Цю дію не можна скасувати.',
