    'admin_shadow-saas-grip.zscaler_api_key_placeholder' => 'Лише для застарілої автентифікації /authenticatedSession',
    'admin_shadow-saas-grip.zscaler_api_url_help' => 'База OneAPI: <code>https://api.zsapi.net</code> (універсальна). Застаріла для окремих хмар: <code>https://zsapi.&lt;cloud&gt;.net</code> (наприклад, <code>zscaler</code>, <code>zscalerone</code>, <code>zscalertwo</code>, <code>zscalerthree</code>, <code>zscloud</code>).',
    'admin_shadow-saas-grip.zscaler_config_update_failed_prefix' => 'Не вдалося оновити конфігурацію Zscaler: ',
