    'admin_shadow-saas-grip.zscaler_connection_heading' => 'З\'єднання з Zscaler',
    'admin_shadow-saas-grip.zscaler_enable_help' => 'Коли увімкнено, кнопка Deny у Shadow SaaS додаватиме домен постачальника до налаштованої URL-категорії. Коли вимкнено, Deny лише оновлює локальний стан.',
    'admin_shadow-saas-grip.zscaler_intro' => 'Коли постачальнику відмовлено у списку Shadow SaaS, домен постачальника додається до наведеної нижче URL-категорії в Zscaler ZIA (з використанням <code>action=ADD_TO_LIST</code>), після чого активується. Спільне для обох провайдерів.',
    'admin_shadow-saas-grip.zscaler_password_help' => '<code>client_secret</code>, показаний <strong>одноразово</strong> під час створення API Client. Зберігається у зашифрованому вигляді. Залиште порожнім, щоб зберегти наявне значення.',
    'admin_shadow-saas-grip.zscaler_password_placeholder' => 'client_secret з API Client',
