    'admin_shadow-saas-grip.zscaler_username_help' => '<code>client_id</code> з API Client, створеного в розділі <strong>ZIdentity → Integration → API Clients</strong>. Має бути надано роль із правами читання/запису ZIA URL Categories.',
    'admin_shadow-saas-grip.zscaler_username_placeholder' => 'UUID з ZIdentity → Integration → API Clients',
    'admin_shadow-saas-grip.zscaler_vanity_help' => 'Хост кінцевої точки токена OAuth тенанта ZIdentity - URL токена: <code>https://&lt;vanity&gt;/oauth2/v1/token</code>. Знайдіть це в URL-адресі адміністратора ZIdentity (частина перед <code>.zslogin.net</code>).',
    'admin_shadow-saas-grip.zscaler_vanity_label' => 'Персональний домен ZIdentity',
    'admin_shodan-srs.about_body' => 'Shodan - це платформа інтернет-аналітики, яка сканує та індексує кожен підключений до інтернету пристрій, який може знайти. Інтеграція забезпечує:<br><br><strong>• Сканування портів:</strong> Виявлення відкритих портів в інфраструктурі постачальника, включно з високоризиковими службами (FTP, Telnet, RDP, SMB)<br><strong>• Виявлення вразливостей:</strong> Виявлення відомих CVE, пов\'язаних з IP-адресами та службами постачальника<br><strong>• Ідентифікація служб:</strong> Каталогізація запущених служб, версій програмного забезпечення та конфігурацій серверів<br><strong>• Оцінювання безпеки:</strong> Генерування балу безпеки від 0 до 100 на основі відкритої поверхні атаки',
    'admin_shodan-srs.about_heading' => 'Про Shodan',
