    'admin_shodan-srs.max_subdomains_help' => 'Кількість субдоменів, які включаються в одне сканування (1-1000). Кожен субдомен споживає кредити API. Типове значення: 20',
    'admin_shodan-srs.max_subdomains_label' => 'Максимум субдоменів для сканування',
    'admin_shodan-srs.min_cve_year_help_prefix' => 'Виключити з результатів сканування CVE, опубліковані до цього року. Типове значення: 0 = автоматично (поточний рік мінус 5, наразі ',
    'admin_shodan-srs.min_cve_year_help_suffix' => '). Виявлення Shodan на основі банерів часто зіставляє дуже старі CVE з рядками версій програмного забезпечення, створюючи хибнопозитивні спрацювання. Установіть конкретний рік для перевизначення або залиште 0, щоб використовувати ковзне 5-річне вікно.',
    'admin_shodan-srs.min_cve_year_label' => 'Мінімальний рік CVE',
    'admin_shodan-srs.min_cve_year_placeholder_prefix' => '0 (типове значення: ',
    'admin_shodan-srs.min_cve_year_placeholder_suffix' => ')',
    'admin_shodan-srs.on_demand_help' => 'Коли ввімкнено, Shodan запитуватиме сканування на вимогу для будь-яких IP-адрес, для яких немає наявних даних, під час оцінювання. Це забезпечує охоплення доменів, які Shodan раніше не сканував, але використовує кредити сканування (1 кредит на IP-адресу) і додає до 3 хвилин часу очікування на кожен запит оцінювання, поки Shodan обробляє сканування. Рекомендовано для постачальників, для яких Shodan не повертає жодних сигналів безпеки.',
    'admin_shodan-srs.on_demand_label' => 'Увімкнути сканування на вимогу',
