    'admin_shodan-srs.rescan_cooldown_help' => 'Придушувати повторювані запити на повторне сканування для IP-адрес, які вже повторно скановано в межах цього вікна. Кожне повторне сканування списує кредити сканування Shodan, тож це запобігає випадковим повторним списанням через подвійні кліки чи послідовні ручні повторні сканування. Установіть 0, щоб вимкнути період очікування (кожен клік повторно сканує кожну IP-адресу). Типове значення: 24 години.',
