    'admin_shodan-srs.weights_warning' => 'Ваги не дають у сумі 100% - вони будуть нормалізовані пропорційно під час обчислення підсумкового балу.',
    'admin_shodan-srs.word_vendor' => 'постачальника',
    'admin_shodan-srs.word_vendors' => 'постачальників',
    'admin_shodan-srs.word_waiver' => 'виключення',
    'admin_shodan-srs.word_waivers' => 'виключень',
    'admin_srs.about_custom_body' => 'Користувацьке оцінювання дозволяє вручну вводити бали безпеки для постачальників за допомогою зовнішніх інструментів оцінювання або служб рейтингу.<br><br><strong>Діапазон балів:</strong> 1-100 (відсоткова шкала)<br><strong>Оцінювання:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>Коли існує кілька джерел оцінювання (UpGuard, Shodan, користувацьке), обчислюється та відображається комбінований середній бал по всьому застосунку. Це забезпечує уніфікований огляд стану безпеки кожного постачальника з усіх доступних джерел.',
    'admin_srs.about_custom_heading' => 'Про користувацьке оцінювання',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk забезпечує автоматизовані рейтинги безпеки та безперервний моніторинг сторонніх постачальників. Інтеграція дозволяє:<br><br><strong>• Автоматизоване оцінювання безпеки:</strong> отримуйте миттєві рейтинги безпеки (0-950) для постачальників на основі їхнього зовнішнього стану безпеки<br><strong>• Виявлення ризиків:</strong> автоматично виявляйте ризики безпеки високого, середнього та низького рівня<br><strong>• Аналіз тенденцій:</strong> відстежуйте бали безпеки постачальників з часом для виявлення покращень або погіршень<br><strong>• Моніторинг за рівнями:</strong> налаштуйте частоту повторного оцінювання на основі критичності постачальника',
    'admin_srs.about_upguard_heading' => 'Про UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'Дізнатися більше про UpGuard CyberRisk &rarr;',
